from PIL import Image
import numpy as np
a=np.array(Image.open('mol_0043.png').convert('L'))
for y in range(300,330):
    xs=[x for x in range(150,230) if a[y,x]<128]
    # group
    gr=[]
    for x in xs:
        if gr and x-gr[-1][-1]<=1: gr[-1].append(x)
        else: gr.append([x])
    print(y, [(g[0],g[-1]) for g in gr])
"

